/bin/bash -lc "python3 - <<'PY'
import json,collections,re
p=json.load(open('packet.json'))
print('ITEMS',len(p['items']))
for x in p['items']:
 q=x['question']
 if q.startswith('Which Rel-'):
  v=re.search(r'Which (Rel-\\d+) change requests that modify clause (.*?) of TS ([\\d.]+) have',q).groups(); kind='clause '+str(v)
 elif q.startswith('Trace change request'):
  kind='trace '+str(re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups())
 elif q.startswith('Change request'):
  kind='decision '+str(re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups())
 elif q.startswith('In which'):
  kind='pack '+str(re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups())
 elif q.startswith('TSG RAN CR pack'):
  kind='members '+re.search(r'RP-\\d+',q).group()
 elif q.startswith('RAN2 recorded document'):
  kind='revision '+re.search(r'R2-\\d+',q).group()
 else:
  kind=q
 print(x['id'],kind,'FIELDS',','.join(x['fields']))
PY"

